                    <td style="font-weight:900;color:#0369a1;">${fmtNum(r.receiveQty)}</td>
                    <td>${fmtNum(r.factor)}</td>
                    <td style="font-weight:800;color:#059669;">${fmtNum(r.baseQty)}</td>
